The following ESP32 C code implements Blake2b-256 for CKB script hash computation on embedded hardware. It contains two serious bugs: a buffer overflow in the padding logic, and incorrect initialisation when using a personalisation string.

```c
#include <stdint.h>
#include <string.h>

// Blake2b constants
static const uint64_t BLAKE2B_IV[8] = {
  0x6a09e667f3bcc908ULL, 0xbb67ae8584caa73bULL,
  0x3c6ef372fe94f82bULL, 0xa54ff53a5f1d36f1ULL,
  0x510e527fade682d1ULL, 0x9b05688c2b3e6c1fULL,
  0x1f83d9abfb41bd6bULL, 0x5be0cd19137e2179ULL
};

#define BLAKE2B_BLOCKBYTES 128

typedef struct {
  uint64_t h[8];      // hash state
  uint64_t t[2];      // counter
  uint64_t f[2];      // finalization flags
  uint8_t  buf[BLAKE2B_BLOCKBYTES];
  size_t   buflen;
} blake2b_state;

void blake2b_init(blake2b_state *S, size_t outlen) {
  memset(S, 0, sizeof(blake2b_state));
  memcpy(S->h, BLAKE2B_IV, sizeof(BLAKE2B_IV));
  // Parameter block: p[0] = digest_length | fanout<<8 | depth<<16 | ...
  S->h[0] ^= 0x01010000ULL ^ (uint64_t)outlen;
}

void blake2b_init_with_personal(blake2b_state *S, size_t outlen, const uint8_t *personal, size_t personal_len) {
  blake2b_init(S, outlen);
  // XOR personalisation into h[7] — BUG 1: personalisation must be zero-padded to 16 bytes
  // and XORed into h[7] AS PART OF the parameter block, not added after init
  uint64_t p;
  memcpy(&p, personal, sizeof(uint64_t));  // Only copies first 8 bytes, ignores bytes 8-15
  S->h[7] ^= p;  // Wrong: should XOR full 16-byte personal into h[6] and h[7] during init
}

void blake2b_update(blake2b_state *S, const uint8_t *in, size_t inlen) {
  while (inlen > 0) {
    size_t left = S->buflen;
    size_t fill = BLAKE2B_BLOCKBYTES - left;

    if (inlen > fill) {
      memcpy(S->buf + left, in, fill);
      S->buflen += fill;
      // increment counter
      S->t[0] += BLAKE2B_BLOCKBYTES;
      if (S->t[0] < BLAKE2B_BLOCKBYTES) S->t[1]++;
      blake2b_compress(S, S->buf);
      S->buflen = 0;
      in += fill;
      inlen -= fill;
    } else {
      memcpy(S->buf + left, in, inlen);
      S->buflen += inlen;
      break;
    }
  }
}

void blake2b_final(blake2b_state *S, uint8_t *out, size_t outlen) {
  // BUG 2: Buffer overflow — pads BLAKE2B_BLOCKBYTES bytes from current buflen,
  // but if buflen is already BLAKE2B_BLOCKBYTES, this writes 128 bytes past end of buf
  memset(S->buf + S->buflen, 0, BLAKE2B_BLOCKBYTES);  // Should be: BLAKE2B_BLOCKBYTES - S->buflen

  S->t[0] += (uint64_t)S->buflen;
  if (S->t[0] < S->buflen) S->t[1]++;
  S->f[0] = (uint64_t)-1;  // set finalization flag

  blake2b_compress(S, S->buf);

  // Output
  memcpy(out, S->h, outlen);
}
```

For each bug:
1. Identify the exact line(s) affected
2. Classify the bug type (buffer overflow / incorrect crypto init / etc.)
3. Describe the failure mode on ESP32 specifically — what happens at runtime?
4. Show the corrected code

Also answer: For CKB's Blake2b-256 (used for script hashes, transaction hashes), does CKB use personalisation? If so, what is the personalisation string?
